/* Quechua Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Sisa": "flower — Quechua sisa", "Wayra": "wind — Quechua wayra", "Inti": "sun — Quechua inti", "Killa": "moon — Quechua killa", "Yupanqui": "he who honors, he who counts — Quechua yupay", "Tupac": "shining, royal — Quechua thupaq", "Huaman": "A common Quechua surname meaning falcon.", "Condori": "A surname after the Andean condor.", "Mamani": "A widespread Andean surname meaning falcon.", "Quispe": "One of the most common Quechua surnames in Peru and Bolivia."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Sisa';
console.log(lookup(q));

